entries.example:
on break:
    if player does not have permission "builder":
        cancel event

on chat:
    if message is "help":
        send "Try /rules" to player

on damage:
    if damage > 10:
        cancel event

on drop:
    if event-item is diamond:
        cancel event

on inventory click:
    if clicked slot is 4:
        cancel event

on level change:
    if new level > old level:
        send "level up!" to player

on load:
    if {spawn} is not set:
        set {spawn} to location(0, 64, 0)

on sneak toggle:
    if player is sneaking:
        send "standing up" to player

loop 10 times:
    if loop-number is 5:
        exit loop

if {coins::%uuid of player%} >= 10:
    send "rich" to player
else:
    send "poor" to player

set {_i} to 0
while {_i} < 5:
    add 1 to {_i}

on chat:
    if message ends with "?":
        send "good question" to player

on chat:
    if message starts with "!":
        cancel event

on chat:
    if message contains "hello":
        send "hi!" to player

on right click:
    if clicked block is chest:
        send "a chest" to player

on damage:
    if attacker is set:
        send "%attacker% hit you for %damage%" to victim

on mob spawn:
    if event-entity is a creeper:
        cancel event

on projectile hit:
    if hit player is set:
        send "ouch" to hit player
